<script lang="ts">
  type Scenario={label:string;description:string;value:string;report:boolean}
  const scenarios:Scenario[]=[{label:'200 OK',description:'Confirms the helper endpoint is reachable.',value:'ok',report:false},{label:'400 Bad Request',description:'Expected client error; remains quiet.',value:'bad-request',report:false},{label:'404 Not Found',description:'Expected missing resource; remains quiet.',value:'not-found',report:false},{label:'429 Rate Limit',description:'Expected throttling; remains quiet.',value:'rate-limit',report:false},{label:'500 Server Error',description:'Cloudflare telemetry records a server failure.',value:'error',report:true},{label:'503 Unavailable',description:'Mirrors a backend incident and is reported.',value:'unavailable',report:true}]
  let pending=$state(''),result=$state<{label:string;ok:boolean;message:string}>()
  async function run(scenario:Scenario){pending=scenario.value;result=undefined;try{const response=await fetch(`/api/admin/frontend-errors/${scenario.value}`);if(!response.ok)throw new Error(`${response.status} ${response.statusText}`);result={label:scenario.label,ok:true,message:'Request completed successfully.'}}catch(cause){result={label:scenario.label,ok:false,message:cause instanceof Error?cause.message:String(cause)}}finally{pending=''}}
  async function network(){pending='network';result=undefined;try{await fetch('https://127.0.0.1:1/gbfm-frontend-error-demo');result={label:'Network failure',ok:true,message:'Unexpectedly completed successfully.'}}catch(cause){result={label:'Network failure',ok:false,message:cause instanceof Error?cause.message:String(cause)}}finally{pending=''}}
</script>
<div class="space-y-6"><section class="rounded border p-5"><h2 class="text-xl font-bold">API response scenarios</h2><p class="mt-2 text-sm text-muted-foreground">Exercise Cloudflare-native browser telemetry and the frontend API failure path.</p><div class="mt-4 grid gap-3 md:grid-cols-2">{#each scenarios as scenario}<article class="flex flex-col gap-3 rounded border p-4"><div class="flex justify-between gap-3"><div><h3 class="font-semibold">{scenario.label}</h3><p class="mt-1 text-sm text-muted-foreground">{scenario.description}</p></div><span class="h-fit rounded-full border px-2 py-1 text-xs">{scenario.report?'Telemetry':'Quiet'}</span></div><button class={`rounded px-4 py-2 ${scenario.report?'bg-destructive text-destructive-foreground':'border'}`} disabled={pending!==''} onclick={()=>void run(scenario)}>{pending===scenario.value?'Running…':'Run scenario'}</button></article>{/each}</div></section><section class="flex flex-col justify-between gap-4 rounded border p-5 sm:flex-row sm:items-center"><div><h2 class="font-bold">Network failure</h2><p class="text-sm text-muted-foreground">Calls an unreachable loopback endpoint to exercise failed-fetch telemetry.</p></div><button class="rounded bg-destructive px-4 py-2 text-destructive-foreground" disabled={pending!==''} onclick={()=>void network()}>{pending==='network'?'Running…':'Run network failure'}</button></section>{#if result}<output class={`block rounded border p-5 ${result.ok?'':'border-destructive/50'}`}><strong>{result.label}</strong><p class="mt-1 text-sm text-muted-foreground">{result.message}</p></output>{/if}</div>
